MARK = object()


class Machine:
    def __init__(self, world, location, *, persistent=False):
        self.world = world
        self.location = location
        self.persistent = persistent
        self.streams = 0

    def one(self, stream):
        stack, memo = [], {}
        protocol = 0
        world = self.world
        self.streams += 1
